const items = $input.all();

return items.map((item) => {
  const text = item.json.candidates?.[0]?.content?.parts?.[0]?.text;

  if (!text) {
    throw new Error('Gemini returned no text content');
  }

  let result;

  try {
    result = JSON.parse(text);
  } catch (error) {
    throw new Error(`Invalid JSON from Gemini: ${text}`);
  }

  if (!result.solution) {
    throw new Error('Solution missing from Gemini response');
  }

  if (!Array.isArray(result.queries)) {
    throw new Error('Missing or invalid queries array');
  }

  if (result.queries.length === 0) {
    throw new Error('Queries array returned by Gemini is empty');
  }

  return {
    json: {
      solution: result.solution,
      queries: result.queries,
    },
  };
});

const input = $input.all();
const out = [];
const seen = new Set();

for (let i = 0; i < input.length; i++) {
  const results = input[i].json.results || [];
  const source = $('Split Out Queries').all()[i]?.json || {};
  for (const r of results) {
    if (!r.url) continue;
    const key = r.url.split('#')[0].replace(/\/$/, '');
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({
      json: {
        solution: source.solution,
        searchQuery: source.query,
        title: r.title || '',
        url: r.url,
        content: r.content || '',
        engine: r.engine || ''
      }
    });
  }
}
return out;

const inputs = $input.all();
const sources = $('Top Candidates Filter').all();

return inputs.map((item, index) => {
  const text = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';

  let verdict;

  try {
    verdict = JSON.parse(text);
  } catch (e) {
    verdict = {
      relevant: false,
      score: 0,
      level: 'low',
      reason: 'Invalid JSON response from AI',
      matchedProblem: '',
      canAnswer: false
    };
  }

  const source = sources[index]?.json || {};
  const score = Number(verdict.score || 0);
  const isRelevant = verdict.relevant === true && score >= 0.80;

  return {
    json: {
      ...source,
      relevant: isRelevant,
      matchScore: score,
      relevanceLevel:
        verdict.level ||
        (score >= 0.80 ? 'high' : score >= 0.50 ? 'medium' : 'low'),
      reason: verdict.reason || '',
      matchedProblem: verdict.matchedProblem || '',
      canAnswer: verdict.canAnswer === true
    }
  };
});

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';

let draft = {
  answer: '',
  linkIncluded: false,
  linkReason: '',
  suggestedAnchor: ''
};

try {
  const parsed = JSON.parse(text);

  if (parsed && typeof parsed === 'object') {
    draft = {
      answer: parsed.answer || '',
      linkIncluded: parsed.linkIncluded === true,
      linkReason: parsed.linkReason || '',
      suggestedAnchor: parsed.suggestedAnchor || ''
    };
  }
} catch (e) {
  draft = {
    answer: text,
    linkIncluded: false,
    linkReason: 'Failed to parse AI response',
    suggestedAnchor: ''
  };
}


// Get source from relevance node
let source = {};

try {
  source = $('Relevant >= 0.80').item.json;
} catch (e) {
  try {
    source = $('Relevant >= 0.75').item.json;
  } catch (e) {
    source = {};
  }
}


// Extract platform
let platform = '';

try {
  platform = new URL(
    source.url || 'https://example.com'
  ).hostname;
} catch (e) {
  platform = source.url || '';
}


return [
  {
    json: {
      solutionId:
        source.solution?.id ||
        source.solution?._id ||
        '',

      solutionTitle:
        source.solution?.titleEn ||
        source.solution?.titleTh ||
        source.solution?.title ||
        '',

      solutionUrl:
        source.solution?.url ||
        source.solution?.link ||
        '',

      platform,

      postTitle:
        source.title || '',

      postUrl:
        source.url || '',

      searchQuery:
        source.searchQuery || '',

      matchedProblem:
        source.matchedProblem || '',

      matchScore:
        source.matchScore || 0,

      relevanceReason:
        source.reason || '',

      answer:
        draft.answer,

      linkIncluded:
        draft.linkIncluded,

      linkReason:
        draft.linkReason,

      suggestedAnchor:
        draft.suggestedAnchor,

      status: 'pending_review'
    }
  }
];

const items = $input.all();

if (items.length === 0) {
  return [];
}

const groupedBySolution = {};

function tokenize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    .filter(word => word.length > 2);
}

for (const item of items) {
  const json = item.json;

  const sol = json.solution || {};

  const solutionId =
    json.solutionId ??
    sol.id ??
    'unknown';

  const solutionTitle =
    json.solutionTitle ||
    sol.title ||
    '';

  const solutionDescription =
    json.solutionDescription ||
    sol.description ||
    '';

  const solutionUrl =
    json.solutionUrl ||
    sol.url ||
    '';

  const solKey = String(solutionId);

  if (!groupedBySolution[solKey]) {
    groupedBySolution[solKey] = [];
  }

  // --------------------------------
  // Solution
  // --------------------------------

  const solutionText = `
    ${solutionTitle}
    ${solutionDescription}
  `;

  const solutionTokens = new Set(
    tokenize(solutionText)
  );

  // --------------------------------
  // Search result
  // --------------------------------

  const title = String(json.title || '');
  const content = String(json.content || '');
  const searchQuery = String(json.searchQuery || '');

  const resultText = `
    ${title}
    ${content}
  `;

  const resultTokens = tokenize(resultText);

  // --------------------------------
  // Calculate token overlap
  // --------------------------------

  let matches = 0;

  for (const token of resultTokens) {
    if (solutionTokens.has(token)) {
      matches++;
    }
  }

  let overlapScore = 0;

  if (
    solutionTokens.size > 0 &&
    resultTokens.length > 0
  ) {
    overlapScore =
      matches /
      Math.sqrt(
        solutionTokens.size *
        resultTokens.length
      );
  }

  // --------------------------------
  // Title bonus
  // --------------------------------

  const titleTokens = tokenize(title);

  let titleMatches = 0;

  for (const token of titleTokens) {
    if (solutionTokens.has(token)) {
      titleMatches++;
    }
  }

  const titleBonus = Math.min(
    0.3,
    titleMatches * 0.05
  );

  // --------------------------------
  // Search query bonus
  // --------------------------------

  const queryTokens = tokenize(searchQuery);

  let queryMatches = 0;

  for (const token of queryTokens) {
    if (solutionTokens.has(token)) {
      queryMatches++;
    }
  }

  let queryBonus = 0;

  if (queryTokens.length > 0) {
    queryBonus = Math.min(
      0.2,
      (queryMatches / queryTokens.length) * 0.2
    );
  }

  // --------------------------------
  // Final score
  // --------------------------------

  const similarityScore = Math.min(
    1,
    overlapScore +
    titleBonus +
    queryBonus
  );

  // --------------------------------
  // Preserve Solution metadata
  // --------------------------------

  item.json.solutionId = solutionId;
  item.json.solutionTitle = solutionTitle;
  item.json.solutionUrl = solutionUrl;

  item.json.similarityScore = Number(
    similarityScore.toFixed(3)
  );

  groupedBySolution[solKey].push(item);
}

// ========================================
// Top 5 per Solution
// ========================================

const topCandidates = [];

for (const [solutionId, group] of Object.entries(
  groupedBySolution
)) {
  group.sort(
    (a, b) =>
      b.json.similarityScore -
      a.json.similarityScore
  );

  const top5 = group.slice(0, 10);

  topCandidates.push(...top5);
}

// ========================================
// Debug
// ========================================

console.log(
  'Total input:',
  items.length
);

console.log(
  'Grouped solutions:',
  Object.entries(groupedBySolution).map(
    ([id, group]) => ({
      solutionId: id,
      count: group.length,
    })
  )
);

console.log(
  'Total output:',
  topCandidates.length
);

return topCandidates;

const items = $input.all();
const out = [];

for (const item of items) {
  const queries = item.json.queries || [];
  const sol = item.json.solution || {};

  for (const q of queries) {
    if (!q || typeof q !== 'string') continue;
    out.push({
      json: {
        solution: sol,
        query: q
      }
    });
  }
}

return out;

